// El banco de indicadores puede ser personalizado por cada aula desde Configuración.
// Empieza con los valores de fábrica y se sustituye, si existe, por la versión guardada en Supabase.
let INDICATOR_BANK = JSON.parse(JSON.stringify(INDICATOR_BANK_DEFAULT));

function buildIndicatorAreaLookup(){
  const lookup = {};
  Object.keys(INDICATOR_BANK).forEach(age=>{
    lookup[age] = {};
    Object.keys(INDICATOR_BANK[age]).forEach(area=>{
      INDICATOR_BANK[age][area].forEach(text=>{ lookup[age][text] = area; });
    });
  });
  return lookup;
}
let INDICATOR_AREA_LOOKUP = buildIndicatorAreaLookup();

async function loadIndicatorBank(){
  try{
    const res = await window.storage.get('indicator-bank-config', true);
    if(res && res.value){
      const parsed = JSON.parse(res.value);
      if(parsed && typeof parsed === 'object'){ INDICATOR_BANK = parsed; }
    }
  }catch(e){ console.error('Error cargando banco de indicadores personalizado', e); }
  INDICATOR_AREA_LOOKUP = buildIndicatorAreaLookup();
}
async function saveIndicatorBank(){
  try{ await window.storage.set('indicator-bank-config', JSON.stringify(INDICATOR_BANK), true); }
  catch(e){ console.error('Error guardando banco de indicadores', e); }
  INDICATOR_AREA_LOOKUP = buildIndicatorAreaLookup();
}
