// ---------- Colchón de seguridad local ----------
function cacheKey(scope_type, scope_id, key){ return 'diarioRincones_cache::' + scope_type + '::' + scope_id + '::' + key; }
function getPendingWrites(){
  try{ return JSON.parse(localStorage.getItem('diarioRincones_pendingWrites') || '[]'); }catch(e){ return []; }
}
function savePendingWrites(list){
  try{ localStorage.setItem('diarioRincones_pendingWrites', JSON.stringify(list)); }catch(e){}
}
function queuePendingWrite(scope_type, scope_id, key, value){
  const list = getPendingWrites().filter(w => !(w.scope_type===scope_type && w.scope_id===scope_id && w.key===key));
  list.push({ scope_type, scope_id, key, value });
  savePendingWrites(list);
}
async function flushPendingWrites(){
  const list = getPendingWrites();
  if(!list.length) return;
  const remaining = [];
  for(const w of list){
    const { error } = await sb.from('kv_store').upsert(
      { scope_type: w.scope_type, scope_id: w.scope_id, key: w.key, value: w.value, updated_at: new Date().toISOString() },
      { onConflict: 'scope_type,scope_id,key' }
    );
    if(error) remaining.push(w);
  }
  savePendingWrites(remaining);
}
window.addEventListener('online', flushPendingWrites);
setInterval(flushPendingWrites, 30000);

window.storage = {
  async get(key, shared){
    const scope_type = shared ? 'aula' : 'user';
    const scope_id = shared ? window.CURRENT_AULA_ID : (window.CURRENT_USER && window.CURRENT_USER.id);
    if(!scope_id) return null;
    try{
      const { data, error } = await sb.from('kv_store').select('value')
        .eq('scope_type', scope_type).eq('scope_id', scope_id).eq('key', key).maybeSingle();
      if(error) throw error;
      if(!data) return null;
      try{ localStorage.setItem(cacheKey(scope_type, scope_id, key), data.value); }catch(e){}
      return { key, value: data.value, shared };
    }catch(e){
      // Sin conexión: usamos la última copia guardada en este dispositivo, si existe.
      let cached = null;
      try{ cached = localStorage.getItem(cacheKey(scope_type, scope_id, key)); }catch(err){}
      if(cached !== null) return { key, value: cached, shared };
      return null;
    }
  },
  async set(key, value, shared){
    const scope_type = shared ? 'aula' : 'user';
    const scope_id = shared ? window.CURRENT_AULA_ID : (window.CURRENT_USER && window.CURRENT_USER.id);
    if(!scope_id) return null;
    try{ localStorage.setItem(cacheKey(scope_type, scope_id, key), value); }catch(e){}
    const { error } = await sb.from('kv_store').upsert(
      { scope_type, scope_id, key, value, updated_at: new Date().toISOString() },
      { onConflict: 'scope_type,scope_id,key' }
    );
    if(error){
      console.error('storage.set error', error);
      queuePendingWrite(scope_type, scope_id, key, value);
      return { key, value, shared };
    }
    return { key, value, shared };
  },
  async delete(key, shared){
    const scope_type = shared ? 'aula' : 'user';
    const scope_id = shared ? window.CURRENT_AULA_ID : (window.CURRENT_USER && window.CURRENT_USER.id);
    if(!scope_id) return null;
    try{ localStorage.removeItem(cacheKey(scope_type, scope_id, key)); }catch(e){}
    const { error } = await sb.from('kv_store').delete()
      .eq('scope_type', scope_type).eq('scope_id', scope_id).eq('key', key);
    if(error) return null;
    return { key, deleted:true, shared };
  },
  async list(prefix, shared){
    const scope_type = shared ? 'aula' : 'user';
    const scope_id = shared ? window.CURRENT_AULA_ID : (window.CURRENT_USER && window.CURRENT_USER.id);
    if(!scope_id) return { keys: [] };
    let q = sb.from('kv_store').select('key').eq('scope_type', scope_type).eq('scope_id', scope_id);
    if(prefix) q = q.like('key', prefix + '%');
    const { data, error } = await q;
    if(error) return { keys: [] };
    return { keys: data.map(r=>r.key), prefix, shared };
  }
};

