document.getElementById('authPwdLoginBtn').addEventListener('click', async ()=>{
  const email = document.getElementById('authPwdEmailInput').value.trim();
  const pwd = document.getElementById('authPwdInput').value;
  if(!email || !pwd){ alert('Escribe tu email y tu contraseña.'); return; }
  const { data, error } = await sb.auth.signInWithPassword({ email, password: pwd });
  if(error){ alert('No se pudo entrar: ' + error.message); return; }
  window.CURRENT_USER = data.user;
  await afterAuthenticated();
});
let pendingLoginEmail = null;
document.getElementById('authSendLinkBtn').addEventListener('click', async ()=>{
  const email = document.getElementById('authEmailInput').value.trim();
  if(!email){ alert('Escribe tu email.'); return; }
  const { error } = await sb.auth.signInWithOtp({ email, options:{ shouldCreateUser: true } });
  if(error){ alert('No se pudo enviar el código: ' + error.message); return; }
  pendingLoginEmail = email;
  showAuthStep('sent');
});
document.getElementById('authBackToEmailBtn').addEventListener('click', ()=>{
  showAuthStep('login');
});
document.getElementById('authVerifyCodeBtn').addEventListener('click', async ()=>{
  const code = document.getElementById('authCodeInput').value.trim();
  if(!code){ alert('Escribe el código que te llegó por email.'); return; }
  if(!pendingLoginEmail){ alert('Vuelve a escribir tu email primero.'); showAuthStep('login'); return; }
  let { data, error } = await sb.auth.verifyOtp({ email: pendingLoginEmail, token: code, type: 'email' });
  if(error){
    // Fallo conocido de Supabase: el primer código de un usuario nuevo a veces
    // solo valida con type:'signup' en vez de type:'email'. Reintentamos así.
    const retry = await sb.auth.verifyOtp({ email: pendingLoginEmail, token: code, type: 'signup' });
    data = retry.data; error = retry.error;
  }
  if(error){ alert('Código incorrecto o caducado: ' + error.message); return; }
  window.CURRENT_USER = data.user;
  await afterAuthenticated();
});

