async function renderAvisosTutorias(){
  const box = document.getElementById('avisosTutorias');
  if(!box) return;
  if(alumnos.length === 0){
    box.innerHTML = '<div class="no-alert">Añade alumnado para ver avisos de tutorías.</div>';
    return;
  }
  const finStr = trimestreConfig['fin' + trimestreConfig.actual];
  const fin = finStr ? new Date(finStr + 'T23:59:59') : null;
  const today = new Date();
  const daysLeft = fin ? Math.round((fin - today) / 86400000) : null;

  const pending = [];
  for(const child of alumnos){
    const tutorias = await loadChildList(child.id, 'tutorias');
    const has = tutorias.some(t => t.trimestre === trimestreConfig.actual);
    if(!has) pending.push(child.name);
  }

  box.innerHTML = '';
  if(pending.length === 0){
    box.innerHTML = '<div class="no-alert">✅ Todas las familias tienen ya una tutoría registrada en el ' + trimestreConfig.actual + 'º trimestre.</div>';
    return;
  }
  const urgent = daysLeft !== null && daysLeft <= 21;
  const summary = document.createElement('div');
  summary.className = 'alert-item' + (urgent ? ' urgent' : '');
  let msg = `Quedan ${pending.length} familia(s) sin tutoría en el ${trimestreConfig.actual}º trimestre`;
  if(daysLeft !== null){
    msg += daysLeft >= 0 ? ` (quedan ${daysLeft} días para el fin de trimestre)` : ' (¡el trimestre ya ha terminado!)';
  }
  msg += ':';
  summary.textContent = msg;
  box.appendChild(summary);
  const listWrap = document.createElement('div');
  listWrap.style.marginTop = '6px';
  listWrap.innerHTML = pending.map(n=>`<span class="tag" style="background:${urgent ? 'var(--coral)' : 'var(--amarillo)'};display:inline-block;margin:3px 4px 0 0;">${escapeHtml(n)}</span>`).join('');
  box.appendChild(listWrap);
}

function renderRegChildSelector(){
  const sel = document.getElementById('regChildSelect');
  if(alumnos.length === 0){
    sel.innerHTML = '<option value="">Sin alumnado</option>';
    currentRegChildId = null;
    return;
  }
  const sorted = alumnos.slice().sort((a,b)=>a.name.localeCompare(b.name, 'es'));
  sel.innerHTML = sorted.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('');
  if(!currentRegChildId || !alumnos.find(c=>c.id === currentRegChildId)){
    currentRegChildId = sorted[0].id;
  }
  sel.value = currentRegChildId;
}
