function renderConfigAreas(){
  const wrap = document.getElementById('configAreasList');
  wrap.innerHTML = '';
  const areas = INDICATOR_BANK[configAge] || {};
  const areaNames = Object.keys(areas);
  if(areaNames.length === 0){
    wrap.innerHTML = '<div class="empty">No hay áreas cargadas para esta edad. Añade una con el botón de abajo.</div>';
    return;
  }
  areaNames.forEach(areaName=>{
    const block = document.createElement('div');
    block.className = 'cfg-area';
    const head = document.createElement('div');
    head.className = 'cfg-area-head';
    const nameInput = document.createElement('input');
    nameInput.type = 'text';
    nameInput.value = areaName;
    nameInput.title = 'Nombre del área';
    const delAreaBtn = document.createElement('button');
    delAreaBtn.className = 'cfg-icon-btn';
    delAreaBtn.title = 'Eliminar área completa';
    delAreaBtn.innerHTML = '<svg class="icon" viewBox="0 0 24 24"><path d="M3 6h18"/><path d="M8 6V4a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2"/><path d="M19 6l-1 14a1 1 0 0 1-1 1H7a1 1 0 0 1-1-1L5 6"/></svg>';
    head.appendChild(nameInput);
    head.appendChild(delAreaBtn);
    block.appendChild(head);

    const indicators = areas[areaName] || [];
    indicators.forEach((text, idx)=>{
      const row = document.createElement('div');
      row.className = 'cfg-ind-row';
      const ta = document.createElement('textarea');
      ta.value = text;
      const delBtn = document.createElement('button');
      delBtn.title = 'Eliminar indicador';
      delBtn.innerHTML = '<svg class="icon" viewBox="0 0 24 24"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>';
      ta.addEventListener('change', async ()=>{
        const val = ta.value.trim();
        if(val){ INDICATOR_BANK[configAge][areaName][idx] = val; await saveIndicatorBank(); }
        else { ta.value = text; }
      });
      delBtn.addEventListener('click', async ()=>{
        if(!confirm('¿Eliminar este indicador?')) return;
        INDICATOR_BANK[configAge][areaName].splice(idx, 1);
        await saveIndicatorBank();
        renderConfigAreas();
      });
      row.appendChild(ta);
      row.appendChild(delBtn);
      block.appendChild(row);
    });

    const addIndBtn = document.createElement('button');
    addIndBtn.className = 'cfg-add-ind';
    addIndBtn.textContent = '+ Añadir indicador a esta área';
    addIndBtn.addEventListener('click', async ()=>{
      INDICATOR_BANK[configAge][areaName].push('Nuevo indicador');
      await saveIndicatorBank();
      renderConfigAreas();
    });
    block.appendChild(addIndBtn);

    nameInput.addEventListener('change', async ()=>{
      const newName = nameInput.value.trim();
      if(!newName || newName === areaName){ nameInput.value = areaName; return; }
      if(INDICATOR_BANK[configAge][newName]){
        alert('Ya existe un área con ese nombre para esta edad.');
        nameInput.value = areaName;
        return;
      }
      INDICATOR_BANK[configAge][newName] = INDICATOR_BANK[configAge][areaName];
      delete INDICATOR_BANK[configAge][areaName];
      await saveIndicatorBank();
      renderConfigAreas();
    });
    delAreaBtn.addEventListener('click', async ()=>{
      if(!confirm(`¿Eliminar el área "${areaName}" completa, con sus ${indicators.length} indicador(es)?`)) return;
      delete INDICATOR_BANK[configAge][areaName];
      await saveIndicatorBank();
      renderConfigAreas();
    });

    wrap.appendChild(block);
  });
}

