document.getElementById('uploadRosterCsvBtn').addEventListener('click', ()=>{
  document.getElementById('rosterCsvFile').click();
});
document.getElementById('rosterCsvFile').addEventListener('change', async (e)=>{
  const file = e.target.files[0];
  if(!file) return;
  try{
    const text = await file.text();
    const rows = parseCsv(text);
    if(rows.length < 2){ alert('El archivo está vacío o no tiene filas de datos.'); return; }
    const header = rows[0].map(h=>h.trim().toLowerCase());
    const nameIdx = header.indexOf('nombre');
    const ageIdx = header.indexOf('edad');
    const aulaIdx = header.indexOf('aula');
    if(nameIdx === -1 || ageIdx === -1){
      alert('El CSV debe tener al menos las columnas "Nombre" y "Edad" (usa la plantilla descargable como referencia).');
      return;
    }
    const aulaActual = (window.CURRENT_AULA_NOMBRE || '').trim().toLowerCase();
    const numCols = header.length;
    let imported = 0, updated = 0, skippedAula = 0, skippedInvalid = 0;
    for(let i=1; i<rows.length; i++){
      let r = rows[i];
      // Si el CSV no llevaba el nombre entre comillas y el nombre contiene comas
      // (ej. "Apellidos, Nombre"), la fila se habrá partido en más columnas de las
      // esperadas. Como Edad y Aula van siempre al final, recomponemos el nombre
      // uniendo todos los campos sobrantes del principio.
      if(r.length > numCols){
        const extra = r.length - numCols;
        const nameParts = r.slice(nameIdx, nameIdx + 1 + extra).map(p => p.trim());
        const rest = r.slice(nameIdx + 1 + extra);
        r = [...r.slice(0, nameIdx), nameParts.join(', '), ...rest];
      }
      const name = (r[nameIdx] || '').trim();
      // Normaliza la edad: acepta "3", "3.0", "3 años", espacios extra, etc.
      const ageRaw = (r[ageIdx] || '').trim();
      const ageMatch = ageRaw.match(/[345]/);
      const age = ageMatch ? ageMatch[0] : '';
      const aula = aulaIdx > -1 ? (r[aulaIdx] || '').trim() : '';
      if(!name || !age){ skippedInvalid++; continue; }
      if(aulaIdx > -1 && aula && aulaActual){
        const aulaNorm = aula.trim().toLowerCase().replace(/\s+/g,' ');
        const aulaActualNorm = aulaActual.replace(/\s+/g,' ');
        if(aulaNorm !== aulaActualNorm){ skippedAula++; continue; }
      }
      const existing = alumnos.find(c => c.name.trim().toLowerCase() === name.toLowerCase());
      if(existing){ existing.age = age; updated++; }
      else{ alumnos.push({id: uid(), name, age, evaluations:{}, observations:[]}); imported++; }
    }
    if(imported === 0 && updated === 0){
      let why = 'No se ha importado ningún alumno/a.\n';
      why += `Filas leídas del archivo: ${rows.length - 1}.\n`;
      if(skippedAula) why += `Descartadas por no coincidir el Aula: ${skippedAula}.\n`;
      if(skippedInvalid) why += `Descartadas por falta de nombre o edad no válida: ${skippedInvalid}.\n`;
      if(!skippedAula && !skippedInvalid) why += 'No se ha podido explicar por qué se han descartado; revisa que las columnas se llamen exactamente Nombre, Edad y Aula.\n';
      why += `\nAula actual detectada: "${window.CURRENT_AULA_NOMBRE || '(sin aula)'}".`;
      alert(why);
      e.target.value = '';
      return;
    }
    let msg = `Se han añadido ${imported} alumno(s) nuevo(s) y actualizado ${updated}.`;
    if(skippedAula) msg += `\nSe han descartado ${skippedAula} fila(s) de otra aula.`;
    if(skippedInvalid) msg += `\nSe han descartado ${skippedInvalid} fila(s) sin nombre o con edad no válida.`;
    const ok = confirm(msg + '\n\n¿Guardar estos cambios en el listado compartido del aula?');
    if(!ok){ e.target.value = ''; return; }
    await saveAlumnos();
    if(currentView === 'roster') renderRosterEdit();
    alert('Listado de alumnado actualizado correctamente.');
  }catch(err){
    alert('No se pudo leer el archivo. Comprueba que es un CSV válido.');
    console.error(err);
  } finally {
    e.target.value = '';
  }
});

// ---------- Init ----------
async function init(){
  document.getElementById('loading').style.display = 'none';
  const { data: { session } } = await sb.auth.getSession();
  if(session){
    window.CURRENT_USER = session.user;
    await afterAuthenticated();
  } else {
    showAuthGate();
    showAuthStep('login');
  }
  sb.auth.onAuthStateChange(async (event, newSession)=>{
    if(event === 'SIGNED_IN' && newSession && (!window.CURRENT_USER || window.CURRENT_USER.id !== newSession.user.id)){
      window.CURRENT_USER = newSession.user;
      await afterAuthenticated();
    }
  });
}
init();

if('serviceWorker' in navigator){
  window.addEventListener('load', ()=>{
    navigator.serviceWorker.register('/service-worker.js').catch(err=>console.error('SW error', err));
  });
}
